//! Each game's hook points by their permanent ids (docs/port/MODS.md, section 4): a manifest may
//! name a hook point by its id (`rac1.player.turn_to_heading`) or by its name
//! (`Hero_TurnToHeading`), and two mods that name it either way share it. The table is generated by
//! sdk/tools/gen_binding.py (`hook_ids.json`, beside this file) and built in, since an installed
//! launcher has no copy of the port's.
//!
//! The table is also the list of hook points this launcher's port has, built from the same
//! commit: a mod version that names an id the table does not have needs a newer port
//! ([`missing`]), as one that names a newer mod interface does (plugins.rs, `API_MINOR`).

use std::collections::{HashMap, HashSet};
use std::sync::OnceLock;

/// One game's hook points: names to ids, and the ids.
#[derive(Default)]
struct Game {
    names: HashMap<String, String>,
    ids: HashSet<String>,
}

fn table() -> &'static HashMap<String, Game> {
    static TABLE: OnceLock<HashMap<String, Game>> = OnceLock::new();
    TABLE.get_or_init(|| {
        let v: serde_json::Value = serde_json::from_str(include_str!("hook_ids.json")).unwrap_or_default();
        let mut out = HashMap::new();
        if let Some(games) = v.get("games").and_then(|g| g.as_object()) {
            for (game, names) in games {
                let names: HashMap<String, String> = names
                    .as_object()
                    .map(|m| m.iter().filter_map(|(k, v)| Some((k.clone(), v.as_str()?.to_string()))).collect())
                    .unwrap_or_default();
                let ids = names.values().cloned().collect();
                out.insert(game.clone(), Game { names, ids });
            }
        }
        out
    })
}

/// The id `name` stands for in `game`: itself when it is an id, or a name the table does not have.
pub fn id<'a>(game: &str, name: &'a str) -> std::borrow::Cow<'a, str> {
    match table().get(game).and_then(|g| g.names.get(name)) {
        Some(id) => std::borrow::Cow::Owned(id.clone()),
        None => std::borrow::Cow::Borrowed(name),
    }
}

/// The hooks of `hooks` that this launcher's port does not have for `game`: the ids of that game
/// (`rac1.freeze.update`) the table does not list (a game it has no entry for has none). Only ids
/// are checked: a name (`Hero_TurnToHeading`) may be an alias the table leaves out (a disc's
/// symbol, an old name), and another game's ids (`rac2.*` on a mod for both) are that game's.
pub fn missing(game: &str, hooks: &[String]) -> Vec<String> {
    if game.is_empty() {
        return Vec::new();
    }
    let prefix = format!("{game}.");
    let have = table().get(game);
    hooks.iter().filter(|h| h.starts_with(&prefix) && !have.is_some_and(|g| g.ids.contains(*h))).cloned().collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn names_and_ids_are_one_hook_point() {
        assert_eq!(id("rac1", "Hero_TurnToHeading"), "rac1.player.turn_to_heading");
        assert_eq!(id("rac1", "rac1.player.turn_to_heading"), "rac1.player.turn_to_heading");
        assert_eq!(id("rac1", "Moby_Bolt_Update"), "rac1.moby.bolt.update");
        assert_eq!(id("rac1", "Not_A_Hook"), "Not_A_Hook");
        assert_eq!(id("rac2", "Hero_TurnToHeading"), "Hero_TurnToHeading");
    }

    fn hooks(list: &[&str]) -> Vec<String> {
        list.iter().map(|h| h.to_string()).collect()
    }

    #[test]
    fn only_this_games_unknown_ids_are_missing() {
        let have = hooks(&["rac1.player.turn_to_heading", "rac1.moby.bolt.update"]);
        assert!(missing("rac1", &have).is_empty());
        // Names and aliases are not checked; nor is another game's id.
        let other = hooks(&["Hero_TurnToHeading", "func_L00_002124E8", "rac2.test.not_a_hook_point"]);
        assert!(missing("rac1", &other).is_empty());
        let new = hooks(&["rac1.player.turn_to_heading", "rac1.test.not_a_hook_point"]);
        assert_eq!(missing("rac1", &new), ["rac1.test.not_a_hook_point"]);
        assert_eq!(missing("rac2", &other), ["rac2.test.not_a_hook_point"]);
        assert!(missing("rac1", &[]).is_empty());
    }
}
